$_MODULE['<{priceandorder}prestashop>_tutorial_0335b6ca536d6d636bdf088442b44790'] = 'Controleer het ontvangeradres in Instellingen op typefouten, kijk in uw spammap en bevestig dat uitgaande e-mail werkt door een andere module of Geavanceerde parameters > E-mail te testen. Elke aanvraag wordt sowieso opgeslagen in het tabblad Offerteaanvragen, dus u kunt deze daar altijd vinden.';
$_MODULE['<{priceandorder}prestashop>_tutorial_0431a668e8d90860362093b461947781'] = 'Dien een testaanvraag in via uw winkel en controleer of deze aankomt in het tabblad Offerteaanvragen en in uw mailbox.';
