$_MODULE['<{priceandorder}prestashop>_tutorial_231cf4c70d866b616c21baddaeed0696'] = 'Probleemoplossing';
$_MODULE['<{priceandorder}prestashop>_tutorial_46ec8e9cec078e1824c2285289a9845a'] = 'Dit komt bijna altijd door de automatische spambeveiliging: het formulier sneller dan 3 seconden na het laden van de pagina verzenden, meer dan een uur na het laden verzenden, of meer dan 5 aanvragen in een uur vanaf dezelfde verbinding. Vraag hen de pagina te vernieuwen en opnieuw te proberen.';
$_MODULE['<{priceandorder}prestashop>_tutorial_487e540af0ce1574b40b98daaf9a704e'] = 'Een bezoeker zegt dat het formulier hun inzending heeft geweigerd.';
