$_MODULE['<{priceandorder}prestashop>_tutorial_a7821d5fcb146c5ad0b90884e504d314'] = 'Uploads zijn beperkt tot JPG-, PNG-, GIF- of WEBP-bestanden tot 4 MB en worden automatisch verkleind tot maximaal 400x280 px met behoud van verhoudingen, zodat het bestand zelf nooit vervormd wordt.';
$_MODULE['<{priceandorder}prestashop>_tutorial_bc9e9fef06497c843ddb85f457c24635'] = 'Ingelogde klanten worden nooit om naam of e-mail gevraagd &mdash; hun accountgegevens worden automatisch gebruikt.';
$_MODULE['<{priceandorder}prestashop>_tutorial_bd4b0999a932632905b77cd2fbc0a97c'] = 'Spambeveiliging is automatisch: een verborgen valveld en een korte vertragingcontrole blokkeren geautomatiseerde inzendingen stil, en er worden maximaal 5 aanvragen per uur van dezelfde bezoeker geaccepteerd. Een echte bezoeker hoeft niets op te lossen.';
$_MODULE['<{priceandorder}prestashop>_tutorial_cb59b87e00d11222bfd9159d0d23836f'] = 'Aan de slag';
$_MODULE['<{priceandorder}prestashop>_tutorial_e41d93a6e7c1aa5aab80cb4cab9dc886'] = 'Er verschijnt een meldingskaart op uw Dashboard wanneer er nieuwe aanvragen zijn, met een directe link naar dit tabblad Offerteaanvragen. Deze verdwijnt zodra elke nieuwe aanvraag als afgehandeld is gemarkeerd of verwijderd.';
$_MODULE['<{priceandorder}prestashop>_tutorial_ea67abf8988cbc6b378a032f822801f8'] = 'Open het tabblad Instellingen en voer het e-mailadres of de e-mailadressen in die offerteaanvragen moeten ontvangen.';
